/**
 * Tenant context plus the project named by `[projectSlug]`.
 *
 * Owner D. Private to the tenant subtree. Every page under
 * `projects/[projectSlug]` needs the same four values, and resolving the
 * project through `ProjectService` (rather than the repository) is what applies
 * the visibility rules — a `private` project the caller is not on must 404,
 * not merely render empty.
 */

import { notFound } from "next/navigation";
import { getProject } from "@/server/services/project-service";
import type { ProjectWithStats } from "@/types/project";
import { loadTenantContext, type TenantContext } from "./tenant-context";

export type ProjectContext = TenantContext & {
  readonly project: ProjectWithStats["project"];
  readonly stats: ProjectWithStats["stats"];
};

export async function loadProjectContext(
  orgSlug: string,
  projectSlug: string,
): Promise<ProjectContext> {
  const tenant = await loadTenantContext(orgSlug);

  const found = await findProject(tenant, projectSlug);
  if (found === null) {
    notFound();
  }

  return { ...tenant, project: found.project, stats: found.stats };
}

/**
 * "Does not exist" and "you may not see it" both come back as `null`, so the
 * two cases are indistinguishable from outside — the same reasoning as the
 * organization lookup in `tenant-context.ts`.
 */
async function findProject(
  tenant: TenantContext,
  projectSlug: string,
): Promise<ProjectWithStats | null> {
  try {
    return await getProject(tenant.actor, tenant.org.id, projectSlug);
  } catch {
    return null;
  }
}
"use server";

/**
 * Updates project metadata.
 *
 * Owner D. Visibility is part of this payload, which is why the permission
 * resource carries the *incoming* visibility: raising a project to `public`
 * must be judged against what it is becoming, not what it was.
 *
 * Must call (do not reimplement): updateProjectSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { updateProjectSchema, type UpdateProjectInput } from "@/schemas/project";
import { updateProject } from "@/server/services/project-service";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";

const run = withAction<typeof updateProjectSchema, Project>(
  updateProjectSchema,
  async (raw, actor) => {
    const input = raw as UpdateProjectInput;

    const allowed = can(actor, "project:update", {
      kind: "project",
      orgId: input.orgId,
      projectId: input.projectId,
      visibility: input.visibility ?? "org",
      leadId: input.leadId ?? actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:update");
    }

    const project = await updateProject(actor, input);
    revalidateTagged([projectTag(project.id)], CACHE_PROFILES.minutes);
    return project;
  },
  { revalidate: ["projects"], cacheProfile: "minutes" },
);

export async function updateProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}
/**
 * Cache tag vocabulary and revalidation helpers.
 *
 * Next 16 requires a cache-life profile as the second argument to
 * `revalidateTag`, which is exactly the kind of API change that rots when it
 * is spelled out at forty call sites. Server Actions call
 * `revalidateTagged([...])` and never import `next/cache` themselves.
 */
import { revalidateTag } from "next/cache";
import type { IssueId, OrgId, ProjectId } from "@/types/common";

/** The cache-life profiles this app uses, by how stale a read may be. */
export const CACHE_PROFILES: Readonly<
  Record<"seconds" | "minutes" | "hours", string>
> = {
  seconds: "seconds",
  minutes: "minutes",
  hours: "hours",
};

export function orgTag(orgId: OrgId): string {
  return `org:${orgId}`;
}

export function projectTag(projectId: ProjectId): string {
  return `project:${projectId}`;
}

export function issueTag(issueId: IssueId): string {
  return `issue:${issueId}`;
}

/**
 * Invalidates every supplied tag under one profile, de-duplicating first so a
 * caller can splice together tag lists without worrying about repeats.
 */
export function revalidateTagged(
  tags: readonly string[],
  profile: string = CACHE_PROFILES.minutes,
): void {
  for (const tag of new Set(tags)) {
    if (tag === "") continue;
    revalidateTag(tag, profile);
  }
}

