export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = await requireVisibleProject(
    actor,
    input.orgId,
    input.projectId,
    "Project",
    input.projectId,
