import * as issueService from "@/server/services/issue-service";
import { NotFoundError } from "@/server/services/_support";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Comment } from "@/types/comment";
import type { OrgId } from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

let cleanup: () => void;
let tenant: Tenant;
let outsider: Tenant;
let orgId: OrgId;
let staff: Actor;

/** Private, no lead, no members: only role and staff grants reach it. */
let hidden: Project;
/** Private, led by the plain member. */
let memberLed: Project;
/** Private, no lead; the plain viewer is added to it in one test. */
let shared: Project;
let publicProject: Project;

let hiddenIssue: Issue;
let memberLedIssue: Issue;
let hiddenComment: Comment;

function insertProjectFor(
  overrides: Pick<Project, "name" | "slug" | "key" | "visibility" | "leadId">,
): Promise<Project> {
  return projectRepo.insertProject({
    orgId,
    name: overrides.name,
    slug: overrides.slug,
    key: overrides.key,
    description: null,
    visibility: overrides.visibility,
    leadId: overrides.leadId,
    color: "#6366f1",
    targetDate: null,
  });
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("visibility", "growth");
  outsider = await createTenant("visibilityother", "growth");
  orgId = tenant.org.id;
  staff = { ...tenant.actors.viewer, isPlatformStaff: true };

  hidden = await insertProjectFor({
    name: "Secret",
    slug: "secret",
    key: "SEC",
    visibility: "private",
    leadId: null,
  });
  memberLed = await insertProjectFor({
    name: "Member led",
    slug: "member-led",
    key: "MBR",
    visibility: "private",
    leadId: tenant.userIds.member,
  });
  shared = await insertProjectFor({
    name: "Shared",
    slug: "shared",
    key: "SHR",
    visibility: "private",
    leadId: null,
  });
  publicProject = await insertProjectFor({
    name: "Open house",
    slug: "open-house",
    key: "OPN",
    visibility: "public",
    leadId: null,
  });

  hiddenIssue = await issueService.createIssue(
    tenant.actors.owner,
    issueInput(orgId, hidden.id, { title: "Secret plan" }),
  );
