    tenant.actors.member,
    issueInput(orgId, tenant.project.id, { title: "Platform issue" }),
  );

  hiddenComment = await commentService.createComment(tenant.actors.owner, {
    orgId,
    issueId: hiddenIssue.id,
    body: "Keep this quiet",
    parentId: null,
    mentionedUserIds: [],
  });
});

afterAll(() => {
  cleanup();
});

describe("services/project-service — canViewProject", () => {
  it("shows org and public projects to every actor in the organization", async () => {
    const { member, viewer } = tenant.actors;

    await expect(projectService.canViewProject(viewer, tenant.project)).resolves.toBe(true);
    await expect(projectService.canViewProject(viewer, publicProject)).resolves.toBe(true);
    await expect(projectService.canViewProject(member, publicProject)).resolves.toBe(true);
  });

  it("shows a private project to admins, owners and platform staff", async () => {
    await expect(projectService.canViewProject(tenant.actors.owner, hidden)).resolves.toBe(true);
    await expect(projectService.canViewProject(tenant.actors.admin, hidden)).resolves.toBe(true);
    await expect(projectService.canViewProject(staff, hidden)).resolves.toBe(true);
  });

  it("shows a private project to its lead", async () => {
    await expect(
      projectService.canViewProject(tenant.actors.member, memberLed),
    ).resolves.toBe(true);
  });

  it("hides a private project from members and viewers who are neither lead nor member", async () => {
    await expect(projectService.canViewProject(tenant.actors.member, hidden)).resolves.toBe(false);
    await expect(projectService.canViewProject(tenant.actors.viewer, hidden)).resolves.toBe(false);
    await expect(projectService.canViewProject(tenant.actors.member, shared)).resolves.toBe(false);
  });

  it("shows a private project to an explicit member, from the moment they are added until removed", async () => {
    const { viewer } = tenant.actors;

    await projectMemberRepo.addProjectMember(orgId, shared.id, tenant.userIds.viewer);
    await expect(projectService.canViewProject(viewer, shared)).resolves.toBe(true);

    await projectMemberRepo.removeProjectMember(orgId, shared.id, tenant.userIds.viewer);
    await expect(projectService.canViewProject(viewer, shared)).resolves.toBe(false);
  });

  it("never shows a private project across the organization boundary", async () => {
    await expect(
      projectService.canViewProject(outsider.actors.owner, hidden),
    ).resolves.toBe(false);
  });
});

describe("lookups of a hidden project", () => {
  it("reports a hidden project as NotFoundError, and lets an admin open it", async () => {
    const error: unknown = await projectService
      .getProject(tenant.actors.member, orgId, "secret")
      .catch((caught: unknown) => caught);
    expect(error).toBeInstanceOf(NotFoundError);

    const found = await projectService.getProject(tenant.actors.admin, orgId, "secret");
    expect(found.project.id).toBe(hidden.id);
  });

  it("reports a hidden project's issue as NotFoundError", async () => {
    await expect(
      issueService.getIssue(tenant.actors.viewer, orgId, hiddenIssue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("reports a hidden project's board as NotFoundError", async () => {
    await expect(
      issueService.getBoard(tenant.actors.member, orgId, hidden.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("reports a hidden issue's comment thread as NotFoundError", async () => {
    await expect(
      commentService.getThread(tenant.actors.member, orgId, hiddenIssue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("reports a hidden issue's attachments as NotFoundError", async () => {
    await expect(
      attachmentService.listAttachments(tenant.actors.member, orgId, hiddenIssue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
});

describe("writes into a hidden project", () => {
  it("refuses to update or archive a hidden project and changes nothing", async () => {
    const { member } = tenant.actors;

    await expect(
      projectService.updateProject(member, { orgId, projectId: hidden.id, name: "Renamed" }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      projectService.archiveProject(member, { orgId, projectId: hidden.id, archiveIssues: true }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const stored = await projectRepo.findProjectById(orgId, hidden.id);
    expect(stored?.name).toBe("Secret");
    expect(stored?.archivedAt).toBeNull();
    expect(await issueRepo.countIssues(orgId, hidden.id)).toBe(1);
  });

  it("refuses to restore a hidden archived project and leaves it archived", async () => {
    const archived = await insertProjectFor({
      name: "Archived secret",
      slug: "archived-secret",
      key: "ARC",
      visibility: "private",
      leadId: null,
    });
    await projectService.archiveProject(tenant.actors.owner, {
      orgId,
      projectId: archived.id,
      archiveIssues: false,
    });

    await expect(
      projectService.restoreProject(tenant.actors.member, orgId, archived.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const stored = await projectRepo.findProjectById(orgId, archived.id);
    expect(stored?.archivedAt).not.toBeNull();
  });

  it("refuses every issue write into a hidden project and changes nothing", async () => {
    const { member } = tenant.actors;
    const issueId = hiddenIssue.id;

    await expect(
      issueService.createIssue(member, issueInput(orgId, hidden.id, { title: "Sneaky" })),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.updateIssue(member, { orgId, issueId, title: "Hijacked" }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.changeIssueStatus(member, { orgId, issueId, status: "done" }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.moveIssue(member, { orgId, issueId, toStatus: "done" }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.assignIssue(member, { orgId, issueId, assigneeId: tenant.userIds.member }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.archiveIssue(member, orgId, issueId)).rejects.toBeInstanceOf(
      NotFoundError,
    );

    const stored = await issueRepo.findIssueById(orgId, issueId);
    expect(stored).toMatchObject({
      title: "Secret plan",
      status: "backlog",
      assigneeId: null,
      archivedAt: null,
    });
    expect(await issueRepo.countIssues(orgId, hidden.id)).toBe(1);
  });

  it("refuses to post, edit or delete comments on a hidden issue", async () => {
    const { member } = tenant.actors;

    await expect(
      commentService.createComment(member, {
        orgId,
        issueId: hiddenIssue.id,
        body: "Can I see this?",
        parentId: null,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      commentService.updateComment(member, {
        orgId,
        commentId: hiddenComment.id,
        body: "Edited",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      commentService.deleteComment(member, { orgId, commentId: hiddenComment.id }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const stored = await commentRepo.findCommentById(orgId, hiddenComment.id);
    expect(stored).toMatchObject({ body: "Keep this quiet", archivedAt: null });
    expect(await commentRepo.countComments(orgId, hiddenIssue.id)).toBe(1);
  });

  it("still lets the lead write on their private project", async () => {
    const updated = await issueService.updateIssue(tenant.actors.member, {
      orgId,
      issueId: memberLedIssue.id,
      title: "Member-led plan, revised",
    });
    expect(updated.title).toBe("Member-led plan, revised");
  });
});

describe("listings", () => {
  it("leaves hidden projects out of the project list and its total", async () => {
    const { member } = tenant.actors;
    const everything = await projectRepo.listProjects({ orgId, limit: 100, cursor: null });

    const visible: string[] = [];
    for (const project of everything.items) {
      if (await projectService.canViewProject(member, project)) visible.push(project.id);
    }

    const page = await projectService.listProjects(member, { orgId, limit: 100, cursor: null });
    expect(page.items.map((item) => item.project.id).sort()).toEqual([...visible].sort());
    expect(page.total).toBe(visible.length);
    expect(page.items.map((item) => item.project.slug)).not.toContain("secret");
  });

  it("lists every project to an admin", async () => {
    const everything = await projectRepo.listProjects({ orgId, limit: 100, cursor: null });
    const page = await projectService.listProjects(tenant.actors.admin, {
      orgId,
      limit: 100,
      cursor: null,
    });

    expect(page.total).toBe(everything.total);
    expect(page.items.map((item) => item.project.slug)).toContain("secret");
  });

  it("leaves issues in hidden projects out of the org-wide issue list and its total", async () => {
    const memberPage = await issueService.listIssues(tenant.actors.member, {
      orgId,
      limit: 100,
      cursor: null,
    });
    const titles = memberPage.items.map((issue) => issue.title);
    expect(titles).not.toContain("Secret plan");
    expect(titles).toContain("Member-led plan, revised");
    expect(titles).toContain("Platform issue");
    expect(memberPage.total).toBe(memberPage.items.length);

    const ownerPage = await issueService.listIssues(tenant.actors.owner, {
      orgId,
      limit: 100,
      cursor: null,
    });
    expect(ownerPage.items.map((issue) => issue.title)).toContain("Secret plan");
    expect(ownerPage.total - memberPage.total).toBe(1);
  });
});

describe("membership and lead changes", () => {
  it("applies a new lead immediately, in both directions", async () => {
    const { admin, member, viewer } = tenant.actors;

    await projectService.updateProject(admin, {
      orgId,
      projectId: memberLed.id,
      leadId: tenant.userIds.viewer,
    });
    await expect(projectService.getProject(member, orgId, "member-led")).rejects.toBeInstanceOf(
      NotFoundError,
    );
    await expect(projectService.getProject(viewer, orgId, "member-led")).resolves.toMatchObject({
      project: { id: memberLed.id },
    });

    await projectService.updateProject(admin, {
      orgId,
      projectId: memberLed.id,
      leadId: tenant.userIds.member,
    });
    await expect(projectService.getProject(member, orgId, "member-led")).resolves.toMatchObject({
      project: { id: memberLed.id },
    });
  });
});

