export async function findIssueByNumber(
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): Promise<Issue | null> {
  const row = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        eq(issues.number, issueNumber),
      ),
    )
    .get();
  return row ? toIssue(row) : null;
}

/**
 * An issue is visible when its project is. Undefined when the viewer sees
 * every project, so the query stays a plain scan for them.
 */
function visibleIssuesPredicate(
  orgId: OrgId,
  viewer: ProjectViewer,
): SQL | undefined {
  const visible = visibleProjectsPredicate(orgId, viewer);
  if (visible === undefined) return undefined;

  return inArray(
    issues.projectId,
    getDb()
      .select({ id: projects.id })
      .from(projects)
      .where(and(orgPredicate(projects.orgId, orgId), visible)),
  );
}

