/**
 * Predicate over `projects` for the rows the viewer may see, or `undefined`
 * when they may see all of them. Scoped to `orgId` inside the membership
 * subquery, since `project_members` is tenant-scoped too.
 */
export function visibleProjectsPredicate(
  orgId: OrgId,
  viewer: ProjectViewer,
): SQL | undefined {
  if (viewer.seesAllPrivate) return undefined;

  return or(
    ne(projects.visibility, "private"),
    eq(projects.leadId, viewer.userId),
    inArray(
      projects.id,
      getDb()
        .select({ id: projectMembers.projectId })
        .from(projectMembers)
        .where(
          and(
            orgPredicate(projectMembers.orgId, orgId),
            eq(projectMembers.userId, viewer.userId),
          ),
        ),
    ),
  );
}

